import sys, json; sys.path.insert(0,'/home/claude/skripty')
from stranka import stranka
O='/home/claude/dokuio.com/src/obsah/ch-fr/'
P=lambda n,p:{'nazev':n,'popis':p}
K3=[('Saisissez les données','Ce que vous ne savez pas, laissez-le – une ligne à compléter à la main restera.'),('Vérifiez le texte','Chaque paragraphe peut être modifié.'),('Téléchargez et signez','PDF ou Word, gratuitement.')]
PRIV=('Enregistrez-vous mes données ?','Non. Le document est créé directement dans votre navigateur ; les données ne sont pas envoyées à un serveur.')
CO='Modèle établi selon le Code des obligations suisse (CO).'
def d(slug, ident, nazev, nazevA, popis, kat, il, slova, title, desc, perex, obsahPopis, obsah, online, hodi, nehodi, po, faq, zakony, vt, vd, de, souv=None):
    landing={'title':title,'description':desc,'perex':perex,'obsahPopis':obsahPopis,'obsah':[P(*x) for x in obsah],'kroky':[P(*x) for x in K3],'online':online,'hodiSe':hodi,'nehodiSe':nehodi,'po':[P(*x) for x in po],'faq':[{'q':q,'a':a} for q,a in faq+[PRIV]],'zakony':zakony,'souvisejiciPopis':'D’autres documents, également gratuits.'}
    t=title.replace('{rok}','2026')
    if not 70<=len(desc)<=170: print('DESC',slug,len(desc))
    if len(t)>70: print('TITLE',slug,len(t))
    if not 30<=len(vd)<=170: print('VD',slug,len(vd))
    if len(vt)>70: print('VT',slug,len(vt))
    assert len(faq)>=3, ('FAQ',slug)
    for w in ('modèle','PDF','gratuit'): assert w in t, (slug,w)
    txt=stranka('ch-fr',slug,ident,nazev,nazevA,{'popis':popis,'kategorie':kat,'ilustrace':il,'slova':slova},souv or kat,landing,{'title':vt,'description':vd,'podnadpis':'Gratuit · résultat en PDF et Word · quelques minutes'})
    txt=txt.replace("  souvisejici:", f"  protejsky: {json.dumps({'ch': de})},\n  souvisejici:",1)
    open(O+slug+'.ts','w').write(txt)

